"""Render the self-contained research note from the design-only supplement."""
import json,sys
from html import escape as e
from pathlib import Path
root=Path(__file__).resolve().parents[1]
data=json.loads((root/'knowledge/game-supplement.json').read_text())['architectureBuildResearch']
builds,cases,sources=data['builds'],data['cases'],data['sources']
def cite(ids):return ' / '.join(f'<a href="{e(sources[k]["url"])}">{e(sources[k]["title"])}</a>' for k in ids)
def rows(items):return '<div class="table-wrap"><table><thead><tr><th>現実の意味</th><th>ゲームへ落とす案</th><th>残す判断</th></tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+v+'</td>' for v in row)+'</tr>' for row in items)+'</tbody></table></div>'
css='''*{box-sizing:border-box}body{margin:0;background:#f2f4ef;color:#20382f;font:17px/1.85 -apple-system,BlinkMacSystemFont,"Hiragino Sans",sans-serif}main{max-width:1080px;margin:auto;padding:28px 18px 80px}h1{font-size:clamp(27px,5vw,43px);line-height:1.4;margin:14px 0}h2{font-size:25px;margin:42px 0 18px}h3{font-size:21px;margin:0 0 12px}h4{margin:20px 0 8px}p{margin:8px 0}a{color:#246549;text-underline-offset:4px}.lead{font-size:20px}.note,.source{font-size:14px;color:#50665b}.badge{display:inline-block;font-size:13px;border-radius:8px;background:#e4ece0;color:#2f5d42;padding:3px 9px;margin-bottom:8px}.panel,article{padding:22px;border:1px solid #d4ded1;border-radius:16px;background:#fff;margin:16px 0}.accent{border-left:5px solid #457b54}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.grid article{margin:0}.flow{background:#edf2e9;padding:12px;border-radius:10px;overflow-wrap:anywhere;font-size:15px}.warn{color:#795336;border-top:1px solid #e6e8de;padding-top:12px}.proposal{background:#edf5ef;padding:14px;border-radius:10px}nav{display:flex;flex-wrap:wrap;gap:8px}nav a{display:block;background:#e2eadf;text-decoration:none;border-radius:10px;padding:10px 14px;min-height:44px}table{border-collapse:collapse;width:100%;font-size:15px;min-width:570px}td,th{border:1px solid #d4ded1;padding:12px;text-align:left;vertical-align:top}th{background:#e6eee2}.table-wrap{overflow-x:auto}label{display:block;font-weight:600}select,input,button{font:inherit;color:inherit}select,input[type=search]{width:100%;background:#fff;padding:12px;border:1px solid #a3b5a6;border-radius:10px;min-height:48px}input[type=range]{width:100%;min-height:44px}button{display:block;width:100%;padding:12px;margin:8px 0;background:#edf3e9;border:1px solid #b4c8b6;border-radius:10px;text-align:left;min-height:48px;cursor:pointer}button:hover,button:focus-visible{background:#dbead6}.controls{display:grid;grid-template-columns:2fr 1fr;gap:14px}.meter{height:18px;background:#e5e8e1;border-radius:9px;overflow:hidden;margin:8px 0}.meter span{display:block;height:100%;background:#6b9470;transition:width .15s}.fail{color:#8b452d}.ok{color:#246549}details{border-top:1px solid #e0e5db;padding-top:14px;margin-top:18px}summary{font-weight:700;cursor:pointer;min-height:44px}li{margin:8px 0}section{scroll-margin-top:20px}[hidden]{display:none!important}.small{font-size:15px}.diagram{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:18px 0}.diagram span{padding:12px;background:#e4eddf;border-radius:10px}.feedback{padding:10px;background:#f2eee3}.empty{padding:15px}.noscript{padding:12px;background:#fff6d8}.suggestions a{display:inline-block;margin:4px 8px 4px 0}footer{margin-top:38px;font-size:14px;color:#50665b}@media(max-width:680px){main{padding:18px 14px 60px}.grid,.controls{grid-template-columns:1fr}.panel,article{padding:17px}h2{font-size:23px}}@media print{body{background:white}.controls,nav,.simulator input,.quiz button{display:none}details>*{display:block}article{break-inside:avoid}.grid{display:block}.table-wrap{overflow:visible}table{min-width:0}main{max-width:none}.meter{display:none}}@media(prefers-reduced-motion:reduce){.meter span{transition:none}}'''
html=f'''<!doctype html>
<html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>AWS構築手法からゲームビルドへ</title><style>{css}</style></head>
<body><main><header><span class="badge">調査設計 · 2026年10月8日 · 第1案</span><h1>よいインフラ構成が、<br>ゲームでもよい選択になる。</h1><p class="lead">AWSの構築手法18案を、ゲームの成立条件・効果・代償・苦手な課題へ落とし込みました。</p><p>公式資料29件を自己照合。8ケース・16確認問で、条件変更による推奨ビルドの変化も示します。</p></header>
<div class="panel accent"><h3>今回の提案</h3><p><strong>「要件を満たす構成ほど勝ちやすい」ゲームにする。</strong>処理量、安全性、許容停止時間、データの鮮度、予算などを各ステージの条件にして、構成の選択に意味を持たせます。</p><p>「理想のインフラ」は用途によって変わります。SAAでも安全・回復力・高性能・費用最適化を考えて構成を選びます。ゲームもひとつの構成を常に最強にせず、条件に適合する複数の勝ち筋を推奨する案です。</p><p class="source">根拠：{cite(['exam','wa'])}。ゲームへの対応は本資料の設計提案です。</p><p class="note">現実の構築手法は公式資料をもとに記述し、戦闘効果・ターン・負荷・費用の値は架空の教材モデルとして分けています。採用・ゲーム実装・独立した内容監査は未実施です。</p></div>
<nav aria-label="目次"><a href="#principles">評価の設計</a><a href="#mapping">前回案との対応</a><a href="#prototype">具体的な戦闘案</a><a href="#builds">18ビルド</a><a href="#cases">8ケース</a><a href="#simulation">残存容量を試す</a><a href="#characters">初期キャラ</a><a href="#roadmap">採用順の提案</a><a href="#sources">出典</a></nav>
<section id="principles"><h2>勝敗と報酬を、構成選択へつなぐ</h2><div class="diagram" aria-label="設計の流れ"><span>要件を読む</span>→<span>構成を選ぶ</span>→<span>負荷・障害を受ける</span>→<span>条件を満たして完了</span>→<span>費用・運用を比較</span></div>
<div class="grid"><article><h3>先に必須条件を判定</h3><p>必要な仕事を期限内に完了できたか。保護対象を守ったか。復旧時間・損失・鮮度が許容内かを判定します。</p><p>安全性やデータ損失の未達を、攻撃力や余ったコインの点数で相殺しない案です。</p></article><article><h3>適合した構成同士で比較</h3><p>要件を満たした後に、維持費・使用資源・復旧の手数・運用の複雑さで報酬を比べます。同程度の構成には同程度の報酬を認めます。</p><p>重い構成を常に禁止せず、必要な冗長化や余力には正当な価値を持たせます。</p></article></div>
{rows([('処理能力・需要','攻撃は必要な仕事を処理する力。敵HPを必要仕事量として扱う案。','通常需要は攻撃ではない。期限内の完了と未処理量を確認。'),('可用性とデータ保全','停止した処理枠、復旧待ち、成果の復元点を別々に持つ。','HPひとつで停止時間とデータ損失を混ぜない。'),('安全性','不正要求を防ぐ一方、正規要求を通す。','すべて拒否して無傷でも業務を完了できない。'),('費用と使用資源','行動エナジーとは別に、配置の維持費・処理の使用費を持つ。','台数を増やすと継続支出も増える。価格は教材の仮定値。'),('観測','敵の状態や負荷を把握し、適切な対処を選ぶ。','観測があっても修復手段がなければ直らない。'),('資源効率・持続可能性','単位仕事あたり使用資源を確認する。','料金の安さだけで実際の環境負荷を断定しない。')])}
<p class="note">これは将来のルール案です。現行のHP・3エナジー・通常30カードを今回変更するものではありません。持続可能性の考え方：{cite(['sustain'])}。</p>
<div class="panel"><h3>共通の基礎と、選べる特化を分ける</h3><p>必要最小の権限、必要な通信、データ保護と保存、監視、復旧方針は各ビルドに必要な範囲で持たせます。「セキュリティビルドを選ばないと基本的な保護もない」という設計は避け、守る脅威や強化の方法に個性を持たせます。</p><p>保存時暗号化と認可は別です。S3は新規保存オブジェクトを標準で暗号化しますが、業務上のアクセス制御は引き続き必要です。SSE-KMSなら鍵使用の許可も確認します。</p><p class="source">{cite(['iam','encrypt','kms'])}</p></div>
<details class="panel"><summary>カード、役、ビルドをどう分けるか</summary><ul><li><strong>カード：</strong>処理先、通信許可、観測、データ保存など、構成要素や行動を表す。</li><li><strong>役：</strong>局所的な連携。例：振り分け＋正常な処理先＋利用できるデータで、要求を処理できる。ただし固定3枚は現実の必須構成ではない。</li><li><strong>ビルド：</strong>冒険全体で、負荷・障害・費用の条件に合わせて要素と対処を選ぶ方針。役を1つ揃えただけでは完成しない。</li></ul><p>役の成立で無条件の火力を出すより、条件が揃った処理・切替・再開などの結果へ報酬をつなげます。実サービスの要件とゲームの枚数条件を分けて表示する案です。</p></details></section>
<section id="mapping"><h2>前回のビルド案をどう読み替えるか</h2>
{rows([('攻撃ビルド','並列処理、Auto Scaling、読取分散で仕事を速く処理する。','下流のボトルネック、起動待ち、維持費を残す。'),('要塞ビルド','多層防御、複数AZ、障害隔離を別系統として扱う。','侵害防止・停止対策・データ保全は同じ防御値にしない。'),('状態異常ビルド','観測・原因判別・負荷制御・回復を、状態の扱いとして表す。','AWSの正常なスロットリング等を敵意や必ず悪い状態にしない。'),('ギャンブルビルド','Spot等の中断リスクを保存・再開・代替容量で管理する。','確率で瞬殺して構築の不足を埋めるものにはしない。'),('魔法ビルド','キャッシュ・事前処理で同じ仕事の計算や往復を省く案へ転換。','認可・暗号化・防御を無視する能力とは結びつけない。'),('回復・復活','バックアップ復元、切替、災害復旧へ対応。','過去の成果損失、復旧時間、復元後の確認がある。'),('連撃・ループ・再使用','分割処理、キュー、安全な再試行へ対応。','無限連打は負荷増幅。重複した仕事の報酬は増やさない。'),('ドロー・サーチ','観測・必要要素の確保・構成の組み立てへ対応。','手札を増やすだけでは処理能力や復旧能力は増えない。'),('経済・圧縮','適正容量、不要資源の削減、料金契約へ対応。','契約割引は容量保証ではない。要件を落とす節約は失点。'),('召喚・複製','処理枠の追加、テンプレートによる構成再現へ対応。','追加枠は起動待ちと維持費があり、誤設定も複製される。')])}
<p class="note">対応は設計上の再解釈です。前回の59案をそのままAWSの正しい構築法と認定するものではありません。</p></section>
<section id="prototype"><h2>戦闘へ落とす、具体的なルール案</h2><div class="panel"><p><strong>盤面に残る構成と、手札から使う対処を分ける。</strong>EC2等の処理先は配置として残り、毎ターン仕事を処理します。観測・増設・再試行・復元等は行動札として使う案です。何を配置しているかがビルドの姿になります。</p><p>カード名・構成要素名は教材由来の用語を使い、下の「処理枠」などは相談上の説明語とします。固定3枚役を揃えるだけで、要件達成と認定はしません。</p><p class="note">以下は説明用の仮定数値で、採用数値・AWS性能・料金ではありません。現行攻撃値からの自動変換もしません。</p><ol><li>要求量・期限・鮮度・次の障害を表示。</li><li>3エナジーで配置や対処を行う。増設は次ターンから有効。</li><li>障害で利用できない処理枠を反映。</li><li>有効枠で要求を処理。許可・データ・鮮度も検査。</li><li>キュー期限、復旧待ち、成果保存を更新。</li><li>維持費を払い、次ターンへ。予算不足なら配置を維持できない。</li></ol><p><strong>仮定の基本値：</strong>処理枠1つで10仕事／ターン、維持費1／ターン。配置行動は1エナジー＋投資2、次ターンから使用可能。配置先のAZやデータ到達条件も持ちます。</p><p>ステージは必要仕事量と期限を持ち、復旧時間・許容損失・安全性・予算も提示します。処理完了と必須条件の適合でクリアし、適合後の支出を比べます。敵はサービス名より「AZ停止」「読取集中」「誤削除」などの課題として示す案です。</p></div><div class="grid"><article><h3>複数AZの構成例</h3><p>需要20、AZ-Aに処理枠2つ、AZ-Bにも2つ。振り分けと両側で使えるデータを確保。</p><p>平常容量40、片AZ停止後も20。処理枠の維持費は4。各AZ1枠ずつなら維持費2ですが、停止後10となり未達です。</p><p>成立報酬は「残存容量で継続」。台数だけで防御を増やすものにはしません。</p></article><article><h3>負荷追従の構成例</h3><p>平常需要10で1枠。次ターン需要30を観測し、追加2枠を今ターン配置。</p><p>追加投資4、配置行動2エナジー、維持費は1から3へ増加。予告なしで今ターンに需要30が来ると、今の容量は10のままです。</p></article><article><h3>キャッシュの構成例</h3><p>原本と有効キャッシュを持つ。同じキーの読み取りは、初回取得後の2ターンだけ処理エナジーを1から0にする案。</p><p>更新で該当コピーを無効化。最新必須要求は原本確認が必要。条件付きの再利用で、全攻撃無料化にはしません。</p></article><article><h3>キューの構成例</h3><p>今ターン30仕事を受理し、毎ターン10処理。初回後の未処理20を保留し、合計3ターンで完了。</p><p>期限3なら適合、期限1なら未達。重複した仕事IDの再配送は成果を増やさず、冪等な処理で二重確定を防ぎます。</p></article><article><h3>最小権限の構成例</h3><p>EC2・S3・必要な読取許可を持つIAMロール・通信できる経路を組み、対象データを取得。</p><p>不足した許可では成功しません。全権限で動いても、不要な権限を使われる課題で損失が出ます。安全な正規処理を報酬にします。</p></article><article><h3>バックアップの構成例</h3><p>ターン2の成果を保存し、ターン4に誤削除。復元行動に2エナジー・1ターンを使い、ターン2時点へ戻る案。</p><p>ターン3以降の未保存成果は戻りません。許容損失を超えればHPが戻っても未達。短い保存間隔には保存費用を付けます。</p></article></div><p class="note">各例の維持費や使用費は比較する構成ごとに明記します。例の数字を、実サービスの価格比較として使いません。</p></section>
<section id="builds"><h2>構築手法から作る18ビルド</h2><p>各ビルドは役名の仮称ではなく、学習する構成方針です。現実の成立条件と、そこから考えたゲーム効果を読み比べられます。</p><div class="controls"><div><label for="search">キーワードで探す</label><input id="search" type="search" placeholder="例：冪等、復旧、キャッシュ"></div><div><label for="category">分野で絞る</label><select id="category"><option value="">すべて</option>'''
for category in dict.fromkeys(x['category'] for x in builds):html+=f'<option>{e(category)}</option>'
html+='</select></div></div><p id="result" role="status" aria-live="polite"></p><p id="empty" hidden>該当する案がありません。条件を変えてください。</p>'
for i,x in enumerate(builds,1):
 html+=f'''<article class="build" id="build-{x['id']}" data-category="{e(x['category'])}"><span class="badge">案 {i:02} · {e(x['category'])}</span><h3>{e(x['title'])}</h3><p><strong>狙い：</strong>{e(x['goal'])}</p><p><strong>実際に向く条件：</strong>{e(x['fit'])}</p><p class="flow">{e(x['flow'])}</p><div class="proposal"><strong>ゲーム効果の提案：</strong><p>{e(x['game'])}</p><p><strong>成立条件：</strong>{e(x['trigger'])}</p></div><p class="warn"><strong>ネック・代償：</strong>{e(x['tradeoffs'])}</p><details><summary>苦手な課題・代替案・キャラとの相性</summary><p><strong>現実の限界：</strong>{e(x['failure_behavior'])}</p><p><strong>ステージ／敵の条件：</strong>{e(x['enemy'])}</p><p><strong>比較する別案：</strong>{e(x['alternatives'])}</p><p><strong>前回案との対応：</strong>{e(x['previous_build'])}</p><p><strong>キャラへの入口案：</strong>{e(x['hero'])}</p><p><strong>構成選択の理由：</strong>{e(x['selection_reason'])}</p></details><p class="source">公式資料：{cite(x['source_ids'])}</p><p class="note">分類ID：{e(x['classification_id'])} · 設計候補／未実装</p></article>'''
html+='''</section><section id="cases"><h2>条件を変えると、推奨構成も変わる</h2><p>8つのケースで「何を満たすために選ぶか」を確認します。ここでの数値は教材の仮定です。</p><div class="panel"><label for="scenario">相談したいケースを選ぶ</label><select id="scenario">'''
for x in cases:html+=f'<option value="{x["id"]}">{e(x["title"])}</option>'
html+='</select><p id="scenario-summary" aria-live="polite"></p><div id="suggestions" class="suggestions"></div></div><noscript><p class="noscript">補助機能なしでも、以下の全ケース・解説と18ビルドを読めます。</p></noscript>'
for i,x in enumerate(cases,1):
 html+=f'''<article class="case" id="case-{x['id']}"><span class="badge">ケース {i}</span><h3>{e(x['title'])}</h3><p>{e(x['premise'])}</p><p><strong>条件：</strong>{e(x['constraints'])}</p><p><strong>比較候補：</strong>{' / '.join('<a href="#build-'+id+'">'+e(next(z['title'] for z in builds if z['id']==id))+'</a>' for id in x['recommended'])}</p><p><strong>推奨の理由：</strong>{e(x['why'])}</p><p class="warn"><strong>条件変更：</strong>{e(x['variant'])}</p><details><summary>確認問題2問と解説を開く</summary>'''
 for j,q in enumerate(x['questions'],1):
  html+=f'<div class="quiz" data-id="{q["id"]}"><h4>問{j}：{e(q["prompt"])}</h4>'
  for option in q['options']:html+=f'<button type="button" data-option="{option["id"]}">{e(option["text"])}</button>'
  html+='<p class="feedback" hidden role="status" aria-live="polite"></p><details><summary>正答と全選択肢の理由</summary><ul>'
  for option in q['options']:html+=f'<li><strong>{"正答：" if option["id"]==q["correct_option_id"] else "別案："}{e(option["text"])}</strong><br>{e(option["explanation"])}</li>'
  html+=f'</ul><p>{e(q["rationale"])}</p></details></div>'
 html+=f'</details><p class="source">{cite(x["source_ids"])}</p><p class="note">分類ID：{x["classification_id"]} · 練習用原稿、ゲームへの取り込みは未実施</p></article>'
html+='''</section><section id="simulation"><h2>「2つある」だけでは足りない：残存容量を試す</h2><div class="panel simulator"><p>計算例：需要160、各AZ容量100なら平常は合計200で足りますが、片AZ停止後は100となり60不足します。下の値を変えて、事前余力と費用の関係を見られます。</p><p class="note">このモデルは分散可能な仕事だけを扱い、データ・経路・権限が使える前提です。遅延・DB・複製・起動時間は計算していません。AWSの性能シミュレーターではありません。</p><div class="grid"><div><label for="demand">需要 <output id="demand-value">160</output> 単位／ターン</label><input id="demand" type="range" min="20" max="300" step="10" value="160"></div><div><label for="capacity-a">AZ-Aの容量 <output id="a-value">100</output></label><input id="capacity-a" type="range" min="0" max="300" step="10" value="100"></div><div><label for="capacity-b">AZ-Bの容量 <output id="b-value">100</output></label><input id="capacity-b" type="range" min="0" max="300" step="10" value="100"></div><div><label for="failure">停止条件</label><select id="failure"><option value="none">停止なし</option><option value="a" selected>AZ-A停止</option><option value="b">AZ-B停止</option><option value="both">両AZ停止</option></select></div></div><p id="capacity-result" role="status" aria-live="polite">AZ-A停止後：需要160に対し容量100。60不足。</p><div class="meter" aria-hidden="true"><span id="capacity-bar" style="width:62.5%"></span></div><p id="cost-result">配置を維持する仮定費用：200。停止中も確保資源の費用は残るモデルです。</p><p class="small">費用は容量1単位あたり1の架空値。実料金、停止中の請求ルール、EC2の台数との対応を表すものではありません。「両AZ停止」はこの2枠が失われるシナリオで、同リージョンの全障害を厳密に再現するものではありません。</p></div></section>
<section id="characters"><h2>初期3キャラへの落とし込み案</h2><p>キャラ名は維持し、得意な<strong>設計判断</strong>を分ける案です。職種がAWS機能の実性能を増やす、という意味にはしません。現行の固有レリックは手札・勝利後回復・初手エナジーの差で、以下は将来の見直し案です。</p><div class="grid"><article><h3>SE：要素をつなぐ</h3><p>必要な処理・保存・経路・権限を組み合わせる。構成定義・検証・キャッシュ・安全な再使用へ分岐。</p><p><strong>固有能力案：</strong>構成の不足条件を見つけ、必要な要素を確保しやすくする。テストなしの複製は強化しない。</p><p><strong>学ぶ判断：</strong>何が足りないのか、どこがボトルネックなのか。</p></article><article><h3>SRE：止まり方と戻し方を扱う</h3><p>観測・複数AZ・障害隔離・バックアップと復旧へ分岐。</p><p><strong>固有能力案：</strong>検知から対処へつなぐ、検証済み手順の実行を助ける。未保存のデータを無条件で復活させない。</p><p><strong>学ぶ判断：</strong>どこまで止まってよいか、いつのデータへ戻ってよいか。</p></article><article><h3>クラウドアーキテクト：要件と資源を配分する</h3><p>負荷追従・非同期化・サーバーレス・購入方式・復旧方式へ分岐。</p><p><strong>固有能力案：</strong>需要を見て資源の増減や配置を調整しやすくする。起動待ちや維持費は残す。</p><p><strong>学ぶ判断：</strong>性能・費用・復旧目標の条件に合う構成を選ぶ。</p></article><article><h3>キャラ共通のルール</h3><p>必要な保護と正規処理を全キャラが持つ。どのキャラでも複数の適合ビルドを作れ、苦手な条件には構成変更で対応できる。</p><p>「責任共有モデル＝追加ドロー」等の現行効果は抽象的な復習表現です。新設計では効果の成立を構成の因果関係へ近づけるか、初期レリックの役割を別途見直します。</p></article></div></section>
<section id="roadmap"><h2>まず採用したい核と、進め方</h2><div class="panel"><ol><li><strong>最初の核：</strong>複数AZ・負荷追従・キャッシュ・キュー・最小権限・バックアップの6系統。処理／状態／費用／待ち時間の違いを示しやすい。</li><li><strong>区別を厚くする：</strong>RDSの待機系と読取レプリカ、復旧方式、冪等性と再試行、観測と修復を追加。</li><li><strong>運用と最適化を広げる：</strong>障害隔離・IaC・安全な変更・Spot・適正容量と契約へ展開。</li><li><strong>評価する：</strong>同じ構成を条件が異なる2つのステージで試し、推奨が逆転するか確認。別の構成でも要件を満たせるなら正解として扱う。</li></ol><p>採用順は教材設計の提案で、実装難易度に基づく制限ではありません。全18案を設計候補として残します。</p><h3>避けたい報酬設計</h3><ul><li>台数・レプリカ数を増やすだけで無条件に攻撃と防御が増える。</li><li>キューに入れた時点で仕事が完了したことにする。</li><li>同じ仕事を再試行するたびに成果が増える。</li><li>全通信・全権限の開放や、保護なしの速攻を最適解にする。</li><li>高価な複数リージョン構成を、要件が緩い場面でも常に理想にする。</li></ul><p><strong>今回の範囲：</strong>代表的なインフラ／アプリ構築パターンの調査とゲーム設計。AWSに依らない原理として冗長化・疎結合・キャッシュ・冪等性・IaC等を使い、具体例はSAAに合わせてAWSで示しました。SAA全範囲の網羅や他社クラウドの比較調査を完了した資料ではありません。</p><p><strong>今後の拡充：</strong>オブジェクト／ブロック／ファイルの選択、アクセスパターンに応じたDB選択、取り込み・分析、ハイブリッド接続等も同じ型で追加できます。</p><p class="note">分類は18ビルド＋8ケース＋1評価概念＝27件。公式資料自己照合済み、分類／内容はdraft、取り込みはcandidate。通常30カード、部屋・学習室の問題、既存保存は今回の設計から変更しません。</p></div></section>
<section id="sources"><h2>調査した公式資料</h2><p>無料で閲覧できるAWS公式資料を2026年10月8日に自己照合しました。下の主張が出典側の確認対象です。ゲーム効果・評価方法・仮定数値は本資料の提案です。</p><ol>'''
for k,s in sources.items():html+=f'<li><a href="{e(s["url"])}">{e(s["title"])}</a><br><span class="small">{e(s["claim"])}</span></li>'
html+='''</ol></section><footer>単一HTML。外部フォント・画像・データ取得なしで全文閲覧でき、補助機能も内蔵しています。検索・ケース選択・仮定の容量計算・確認問は端末内で動作し、ゲームの保存や学習記録を書き換えません。印刷／PDF保存にも対応。<p><a href="./character-builds.html">前回の59ビルド案へ</a></p></footer></main>'''
